require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('supervisor');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pid=(int)($_POST['project_id']??0);if(!project_access($pid,$u))$err='Project is not assigned to you.';else{$date=(string)($_POST['meeting_at']??'');$notes=post_string('discussion_notes',5000);$tasks=post_string('tasks_assigned',3000);$type=(string)($_POST['meeting_type']??'in_person');if(!strtotime($date)||!$notes||!in_array($type,['in_person','online','email','other'],true))$err='Provide meeting date, type, and discussion notes.';else{db()->prepare('INSERT INTO supervision_meetings(project_id,supervisor_id,meeting_at,meeting_type,discussion_notes,tasks_assigned,next_meeting_at,status) VALUES(?,?,?,?,?,?,?,"completed")')->execute([$pid,$u['id'],date('Y-m-d H:i:s',strtotime($date)),$type,$notes,$tasks?:null,($_POST['next_meeting_at']??'')?date('Y-m-d H:i:s',strtotime((string)$_POST['next_meeting_at'])):null]);$q=db()->prepare('SELECT student_id FROM project_members WHERE project_id=?');$q->execute([$pid]);foreach($q->fetchAll(PDO::FETCH_COLUMN) as $sid)notify_user((int)$sid,'Supervision meeting recorded','Your supervisor added a meeting record.','info','project',$pid);audit('meeting_recorded','project',$pid,'Supervision meeting recorded');flash('success','Meeting recorded.');redirect('supervisor/meetings.php');}}}$q=db()->prepare('SELECT p.id,p.reference_no,p.title FROM projects p JOIN project_supervisors ps ON ps.project_id=p.id WHERE ps.supervisor_id=? AND ps.ended_at IS NULL');$q->execute([$u['id']]);$projects=$q->fetchAll();$q=db()->prepare('SELECT m.*,p.title,p.reference_no FROM supervision_meetings m JOIN projects p ON p.id=m.project_id WHERE m.supervisor_id=? ORDER BY m.meeting_at DESC');$q->execute([$u['id']]);$meetings=$q->fetchAll();$pageTitle='Supervision Meetings';$crumbTrail=['Meetings'];require dirname(__DIR__).'/includes/header.php';
?>
<?php $now=time();$upcoming=[];$previous=[];foreach($meetings as $m){if(($m['status']??'')==='scheduled'&&strtotime($m['meeting_at'])>=$now-86400)$upcoming[]=$m;else $previous[]=$m;} usort($upcoming,fn($a,$b)=>strcmp($a['meeting_at'],$b['meeting_at']));
 $completed=count(array_filter($meetings,fn($m)=>($m['status']??'')==='completed'));$followUp=count(array_filter($meetings,fn($m)=>!empty($m['tasks_assigned'])));$next=$upcoming[0]['meeting_at']??null; ?>
<div class="row g-3 mb-3">
  <div class="col-md-4"><div class="stat-card"><div class="stat-label">Upcoming</div><div class="stat-value text-blue"><?= count($upcoming) ?></div><small class="stat-sub"><?= $next?'Next: '.e(ui_date($next)):'No meeting scheduled' ?></small></div></div>
  <div class="col-md-4"><div class="stat-card"><div class="stat-label">Completed</div><div class="stat-value text-green"><?= (int)$completed ?></div><small class="stat-sub">Recorded sessions</small></div></div>
  <div class="col-md-4"><div class="stat-card"><div class="stat-label">Follow-up</div><div class="stat-value text-gold"><?= (int)$followUp ?></div><small class="stat-sub">Meetings with assigned tasks</small></div></div>
</div>
<section class="card filter-bar mb-3"><div class="filter-form"><label class="search-box"><?= ui_icon('search') ?><input type="search" class="form-control" placeholder="Search records..." aria-label="Search meetings" data-live-filter=".meeting-row"></label><span class="filter-note">Upcoming &amp; Previous Records</span></div></section>
<details class="card record-card mb-3" <?= $err?'open':'' ?>><summary><span class="section-heading mb-0">Record a meeting</span><span class="chev"><?= ui_icon('chevron',16) ?></span></summary>
<div class="p-4 pt-2"><?php if($err): ?><div role="alert" class="alert alert-danger"><?= e($err) ?></div><?php endif; ?>
<form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label" for="project_id">Project</label><select class="form-select" id="project_id" name="project_id" required><?php foreach($projects as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['reference_no'].' · '.$p['title']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label" for="meeting_at">Meeting date and time</label><input class="form-control" id="meeting_at" type="datetime-local" name="meeting_at" required></div><div class="col-md-3"><label class="form-label" for="meeting_type">Type</label><select class="form-select" id="meeting_type" name="meeting_type"><option value="in_person">In person</option><option value="online">Online</option><option value="email">Email</option><option value="other">Other</option></select></div><div class="col-md-6"><label class="form-label" for="discussion_notes">Discussion notes</label><textarea class="form-control" id="discussion_notes" name="discussion_notes" rows="3" placeholder="What was discussed" required></textarea></div><div class="col-md-6"><label class="form-label" for="tasks_assigned">Tasks assigned</label><textarea class="form-control" id="tasks_assigned" name="tasks_assigned" rows="3" placeholder="Actions agreed with the student"></textarea></div><div class="col-md-4"><label class="form-label" for="next_meeting_at">Next meeting (optional)</label><input class="form-control" id="next_meeting_at" type="datetime-local" name="next_meeting_at"></div><div class="col-12 d-flex justify-content-end"><button class="btn btn-primary">Save meeting record</button></div></div></form></div></details>
<section class="card p-4 mb-3"><h2 class="section-heading">Upcoming Meetings</h2><div class="row-table"><div class="row-table-head">Date / Purpose / Participant / Status</div>
<?php foreach($upcoming as $m): ?><div class="meeting-row"><div><strong><?= e(ui_date($m['meeting_at'],'D, M j, Y · g:i A')) ?> | <?= e(ui_label($m['meeting_type'])) ?> | <?= e($m['reference_no']) ?></strong><p><?= e($m['title']) ?></p></div><?= ui_pill($m['status']??'scheduled') ?></div><?php endforeach; ?>
<?php if(!$upcoming): ?><div class="empty-state m-3">No upcoming meetings.</div><?php endif; ?></div></section>
<section class="card p-4"><h2 class="section-heading">Previous Meeting History</h2><div class="row-table"><div class="row-table-head">Date / Purpose / Participant / Notes / Status</div>
<?php foreach($previous as $m): ?><div class="meeting-row"><div><strong><?= e(ui_date($m['meeting_at'],'M j, Y')) ?> | <?= e(ui_label($m['meeting_type'])) ?> | <?= e($m['reference_no'].' · '.$m['title']) ?></strong><p><?= nl2br(e($m['discussion_notes'])) ?></p><?php if(!empty($m['tasks_assigned'])): ?><p class="task-line"><strong>Tasks:</strong> <?= e($m['tasks_assigned']) ?></p><?php endif; ?><?php if(!empty($m['next_meeting_at'])): ?><p class="task-line"><strong>Next meeting:</strong> <?= e(ui_date($m['next_meeting_at'],'M j, Y · g:i A')) ?></p><?php endif; ?></div><?= ui_pill($m['status']??'completed') ?></div><?php endforeach; ?>
<?php if(!$previous): ?><div class="empty-state m-3">No meeting records yet.</div><?php endif; ?></div></section>
